const int MAXN = 100005;
int a[MAXN];
int tempArr[MAXN];
void mergeArray(int left, int mid, int right) {
    int i = left;       // 左半部分起点
    int j = mid + 1;    // 右半部分起点
    int k = left;       // 临时数组下标
    while (i <= mid && j <= right) {
        if (a[i] <= a[j]) {
            tempArr[k++] = a[i++];
